param(
  [Parameter(Mandatory=$true)][string]$Ffmpeg,
  [Parameter(Mandatory=$true)][string]$FixtureDirectory,
  [Parameter(Mandatory=$true)][string]$NotoFont,
  [Parameter(Mandatory=$true)][string]$FontLicense
)
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath($FixtureDirectory)
foreach($name in @('h264-aac.mkv','hevc-multi-font.mkv','hevc-truehd-aac.mkv','probe-font.ass','Noto-CJK-OFL.txt')) {
  if(Test-Path -LiteralPath (Join-Path $root $name)){throw "Refusing overwrite: $name"}
}
# Inputs must be the synthetic base fixtures generated by generate_playback_fixtures.ps1.
# No existing BDRip or user library is used. Video streams are copied unchanged.
if((Get-FileHash -LiteralPath $NotoFont -Algorithm SHA256).Hash -ne '2C76254F6FC379FDDFCE0A7E84FB5385BB135D3E399294F6EEB6680D0365B74B') {
  throw 'Expected official NotoSansCJKsc-Regular.otf test font'
}
$ass=(Get-Content -Raw -LiteralPath (Join-Path $root 'probe.ass')).Replace('Microsoft YaHei','Noto Sans CJK SC')
[IO.File]::WriteAllText((Join-Path $root 'probe-font.ass'),$ass,[Text.UTF8Encoding]::new($false))
Copy-Item -LiteralPath $FontLicense -Destination (Join-Path $root 'Noto-CJK-OFL.txt')
& $Ffmpeg -v error -n -i (Join-Path $root 'h264-8-1080.mkv') -map 0:v -map 0:a -c:v copy -bsf:v 'h264_metadata=colour_primaries=1:transfer_characteristics=1:matrix_coefficients=1' -c:a aac (Join-Path $root 'h264-aac.mkv')
if($LASTEXITCODE-ne0){throw 'AAC fixture failed'}
& $Ffmpeg -v error -n -i (Join-Path $root 'hevc-main10-1080.mkv') -f lavfi -i 'aevalsrc=0.08*sin(2*PI*440*t)|0.08*sin(2*PI*880*t):s=48000:d=4:c=stereo' -i (Join-Path $root 'probe-font.ass') -map 0:v -map 1:a -map 1:a -map 2:s -c:v copy -c:a:0 flac -c:a:1 aac -c:s ass -attach $NotoFont -metadata:s:t mimetype=application/vnd.ms-opentype -metadata:s:t filename=NotoSansCJKsc-Regular.otf -shortest (Join-Path $root 'hevc-multi-font.mkv')
if($LASTEXITCODE-ne0){throw 'Font/multiple audio fixture failed'}
& $Ffmpeg -v error -n -i (Join-Path $root 'hevc-main10-1080.mkv') -f lavfi -i 'aevalsrc=0.05*sin(2*PI*220*t)|0.05*sin(2*PI*330*t)|0.05*sin(2*PI*440*t)|0.05*sin(2*PI*110*t)|0.05*sin(2*PI*550*t)|0.05*sin(2*PI*660*t):s=48000:d=4:c=5.1' -map 0:v -map 1:a -map 1:a -c:v copy -c:a:0 truehd -strict -2 -c:a:1 aac -ac:a:1 2 -disposition:a:0 default -disposition:a:1 0 -shortest (Join-Path $root 'hevc-truehd-aac.mkv')
if($LASTEXITCODE-ne0){throw 'TrueHD fixture failed'}
